    /// Returns `true` if the decision tree can reach a `Fail` node at runtime,
    /// meaning the patterns it was compiled from are not guaranteed to match.
    /// If this returns `false` we know the match is exhaustive and will always
    /// succeed, so code generation can bind pattern variables using a single
    /// combined declaration (`let x = value;`) instead of hoisting a bare
    /// declaration and reassigning it inside a conditional.
    ///
    pub fn can_fail(&self) -> bool {
        match self {
            Decision::Run { .. } => false,
            Decision::Fail => true,
            Decision::Guard { if_false, .. } => if_false.can_fail(),
            Decision::Switch {
                choices, fallback, ..
            } => {
                fallback.can_fail() || choices.iter().any(|(_, decision)| decision.can_fail())
            }
        }
    }
